window.RP_SESSION={"id":"S-7b83cb645b64","messages":[{"id":"RP-0247709","time":"2026-08-24T00:44:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아도니스는 두려웠다. 그리고 동시에 화가 나있었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247710","time":"2026-08-24T00:45:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 내가 그 때 조금더 기억을 잘해서, 판단을 잘해서 셴이 마녀 사냥꾼인 걸 알았다면 자신과 동료들이 이렇게까지 다치진 않았겠지. 그건 확실히 아도니스의 탓이었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247711","time":"2026-08-24T00:46:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그러면 그 두눈을","characters":["P-6eeed2b4661f"]},{"id":"RP-0247712","time":"2026-08-24T00:46:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"...그 검은 두 눈을 마주치지 않아도 되었을텐데.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247713","time":"2026-08-24T00:47:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아도니스는 두려워 하는게 많았다. 루시와 떨어짐을 두려워했고, 그가 화내는 것을 두려워했고, 정령이 경계하는 것을 두려워했고 자연이 자신을 미워할 것을 두려워했고","characters":["P-6eeed2b4661f"]},{"id":"RP-0247714","time":"2026-08-24T00:47:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"죽음이 두려워...","characters":["P-6eeed2b4661f"]},{"id":"RP-0247715","time":"2026-08-24T00:49:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 루시를 만나지 못할 까봐 두려운 것이 아니었다. 아도니스의 심장이 뛰고 있기에, 뜨거운 피가 몸 속 곳곳에 뛰고 있기에 두려운 것이었다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247716","time":"2026-08-24T00:50:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 자신이 죽음이 두렵기에, 자신의 부상이 싫었다. 자신이 부상이 싫었기에 동료들의 부상이 슬펐다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247717","time":"2026-08-24T00:51:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"어떠한 문제는 영영 해결되지 않는 것처럼, 아도니스가 모든 문제를 피할 순 없는 거였다. 아도니스 역시 그 사실을 알았으나, 부러진 뼈 사이 사이로 만약에가 새어들어와서.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247718","time":"2026-08-24T00:51:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그 검은 두 눈이... 착한 아이가...","characters":["P-6eeed2b4661f"]},{"id":"RP-0247719","time":"2026-08-24T00:52:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 아, 나는 더이상 아이가 아니구나. 더이상은 가족의 품 속에만 있을 수가 없어.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247720","time":"2026-08-24T00:53:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 죽음만큼 두렵고 피할 수 없는 나이 먹음이 아도니스에게 왔다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247721","time":"2026-08-24T00:54:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 괜찮아, 그 모든건 성장이고 퇴화야. 모두 자연의 순환 안에 있어. 착한 아이가 못 된다면 착한 어른이 되면 돼.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247722","time":"2026-08-24T00:55:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 모두 헤어지겠지만, 언젠가 다시 만날 수 있을 거야.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247723","time":"2026-08-24T00:55:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":"아도니스는 그렇게 되뇌이며, 검은 눈의 공포를 떨쳐내려 애썼다.","characters":["P-6eeed2b4661f"]},{"id":"RP-0247724","time":"2026-08-24T00:55:00+09:00","room":"RP","name":"아도니스","profile":"올리브","identity":"reviewed","type":"dialogue","body":" -fin","characters":["P-6eeed2b4661f"]},{"id":"RP-0247725","time":"2026-08-24T00:55:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
